"""Keyframe sampling with a tiny synthetic video generated by ffmpeg."""

from __future__ import annotations

import io
import shutil
import subprocess
from pathlib import Path

import pytest
from PIL import Image
from prometheus_client import REGISTRY

from app.llm.client import LLMClient, LLMError
from app.llm.vision import ImagePart
from app.schemas.extraction import ExtractionResult
from app.services.video_frames import (
    FrameCaption,
    FrameSamplingError,
    Keyframe,
    caption_frames,
    format_timestamp,
    merge_captions,
    recording_to_text,
    sample_keyframes,
)

pytestmark = pytest.mark.skipif(shutil.which("ffmpeg") is None, reason="ffmpeg not installed")

COLOURS = ["black", "white", "blue"]  # strong luma/chroma jumps: scene score well above 0.3


def make_video(path: Path, colours: list[str], seconds_each: int) -> None:
    """A 160x120 5 fps video that holds each colour for ``seconds_each`` seconds."""
    inputs = []
    for c in colours:
        inputs += ["-f", "lavfi", "-i", f"color=c={c}:s=160x120:r=5:d={seconds_each}"]
    concat = "".join(f"[{i}:v]" for i in range(len(colours))) + f"concat=n={len(colours)}"
    subprocess.run(  # noqa: S603
        [shutil.which("ffmpeg"), "-v", "error", "-y", *inputs, "-filter_complex", concat,
         "-pix_fmt", "yuv420p", str(path)],
        check=True,
    )  # fmt: skip


@pytest.fixture(scope="module")
def three_scene_video(tmp_path_factory: pytest.TempPathFactory) -> Path:
    path = tmp_path_factory.mktemp("video") / "scenes.mp4"
    make_video(path, COLOURS, 2)
    return path


def dominant(frame: Keyframe) -> str:
    r, g, b = Image.open(io.BytesIO(frame.image.data)).convert("RGB").getpixel((40, 40))
    if min(r, g, b) > 200:
        return "white"
    return "blue" if b > 150 and r < 80 else "black"


def test_scene_mode_returns_one_frame_per_scene_with_timestamps(three_scene_video: Path) -> None:
    before = REGISTRY.get_sample_value("aoi_ingest_video_frames_total", {"mode": "scene"}) or 0
    frames = sample_keyframes(three_scene_video, mode="scene")
    assert [dominant(f) for f in frames] == COLOURS
    assert [round(f.timestamp) for f in frames] == [0, 2, 4]
    assert all(f.image.media_type == "image/jpeg" for f in frames)
    after = REGISTRY.get_sample_value("aoi_ingest_video_frames_total", {"mode": "scene"})
    assert after == before + 3


def test_interval_mode_samples_on_a_fixed_cadence(three_scene_video: Path) -> None:
    frames = sample_keyframes(three_scene_video, mode="interval", interval=2.0)
    assert [round(f.timestamp) for f in frames] == [0, 2, 4]


def test_static_recording_falls_back_to_interval_sampling(tmp_path: Path) -> None:
    path = tmp_path / "static.mp4"
    make_video(path, ["white"], 6)
    frames = sample_keyframes(path, mode="scene", interval=2.0)
    assert [round(f.timestamp) for f in frames] == [0, 2, 4]


def test_max_frames_thins_evenly(three_scene_video: Path) -> None:
    frames = sample_keyframes(three_scene_video, mode="interval", interval=0.4, max_frames=3)
    assert len(frames) == 3
    assert frames[0].timestamp == 0
    assert frames[-1].timestamp > 4


def test_invalid_inputs(tmp_path: Path) -> None:
    junk = tmp_path / "junk.mp4"
    junk.write_bytes(b"not a video")
    with pytest.raises(FrameSamplingError, match="decoded"):
        sample_keyframes(junk)
    with pytest.raises(ValueError, match="mode"):
        sample_keyframes(junk, mode="burst")


class CaptionStub(LLMClient):
    def __init__(self, fail_at: str | None = None) -> None:
        self.calls: list[str] = []
        self.fail_at = fail_at

    async def extract(self, *a: object, **k: object) -> ExtractionResult:  # pragma: no cover
        raise AssertionError

    async def caption_image(self, image: ImagePart, *, timestamp: str) -> str:
        self.calls.append(timestamp)
        if timestamp == self.fail_at:
            raise LLMError("boom")
        return f"Slide shown at {timestamp}"


async def test_recording_to_text_captions_each_keyframe_in_order(three_scene_video: Path) -> None:
    stub = CaptionStub()
    text = await recording_to_text(stub, three_scene_video)
    assert text == (
        "## Screen captions\n"
        "[00:00] Slide shown at 00:00\n"
        "[00:02] Slide shown at 00:02\n"
        "[00:04] Slide shown at 00:04"
    )
    assert sorted(stub.calls) == ["00:00", "00:02", "00:04"]


async def test_one_failed_caption_is_skipped_but_all_failing_raises() -> None:
    frames = [Keyframe(float(t), ImagePart(b"x", "image/jpeg")) for t in (0, 5)]
    captions = await caption_frames(CaptionStub(fail_at="00:05"), frames)
    assert [c.timestamp for c in captions] == [0.0]

    class AlwaysFails(CaptionStub):
        async def caption_image(self, image: ImagePart, *, timestamp: str) -> str:
            raise LLMError("down")

    with pytest.raises(LLMError, match="No frame"):
        await caption_frames(AlwaysFails(), frames)


def test_merge_puts_audio_before_captions() -> None:
    merged = merge_captions([FrameCaption(65.0, " Jira board ")], "Priya: ship it.")
    assert merged == (
        "## Audio transcript\nPriya: ship it.\n\n## Screen captions\n[01:05] Jira board"
    )


def test_format_timestamp() -> None:
    assert format_timestamp(0) == "00:00"
    assert format_timestamp(3725.9) == "1:02:05"
